'use strict';

// Opt-in acceptance of an exact revert without a fresh AI review. See docs/exact-revert.md.
//
// A pull request is accepted here only when the tree it would leave on the base branch is byte-identical (the same git tree
// object id) to the tree of an earlier commit on the FIRST-PARENT history of the exact base commit the PR is based on,
// within a window set in protected configuration. Every input is read by the engine from the base repository through the
// GitHub API for immutable commit ids: the head tree id, the ancestry of the head, and the history of the base. Nothing is
// taken from the PR title, body, comments or commit messages. Unset, nothing here is called and behaviour is unchanged.

const {digest} = require('./acceptance.cjs');

const MAX_WINDOW = 200;
const PAGE = 100;
const MARKER = '<!-- clouseau-exact-revert:v1 -->';
const object = value => /^[a-f0-9]{40}$/.test(value) || /^[a-f0-9]{64}$/.test(value);

function validate(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value) || Object.keys(value).join(',') !== 'window' ||
      !Number.isInteger(value.window) || value.window < 2 || value.window > MAX_WINDOW) {
    throw new Error(`Invalid exact_revert configuration; use {"window": a whole number of base commits from 2 to ${MAX_WINDOW}}`);
  }
  return value;
}

// The first-parent chain of the base, newest first, from the commits listed for the base commit. A parent that was not
// listed ends the chain: it lies outside the window.
function chain(commits, tip) {
  const bySha = new Map(commits.map(commit => [commit.sha, commit]));
  const links = [];
  for (let commit = bySha.get(tip); commit; commit = bySha.get(commit.parents[0]?.sha)) links.push(commit);
  return links;
}

// A tree is rolled back when a later commit restored the tree that preceded it. Restoring it again would reinstate a state
// the history itself undid, so it needs a real review. A commit whose predecessor lies outside the window cannot be judged
// and is not eligible; a root commit has no predecessor to restore.
function eligible(links) {
  const trees = links.map(commit => commit.commit.tree.sha);
  const rolledBack = new Set();
  const unjudged = new Set();
  links.forEach((commit, index) => {
    if (index === 0 || commit.parents.length === 0) return;
    const before = links[index + 1];
    if (!before) unjudged.add(trees[index]);
    else if (trees.slice(0, index).includes(trees[index + 1])) rolledBack.add(trees[index]);
  });
  return {trees, rolledBack, unjudged};
}

// Decide one pull request. `reason` is a stable sentence for the notice; it never quotes repository content.
async function verify({github, repo, pr, window}) {
  const {data: head} = await github.rest.repos.getCommit({...repo, ref: pr.head.sha});
  if (head.sha !== pr.head.sha || !object(head.commit.tree.sha)) return {matched: false, reason: 'the head commit tree is unavailable'};
  const {data: compared} = await github.rest.repos.compareCommitsWithBasehead({...repo, basehead: `${pr.base.sha}...${pr.head.sha}`});
  if (compared.status !== 'ahead' || compared.merge_base_commit.sha !== pr.base.sha) {
    return {matched: false, reason: 'the pull request is not based on the current base commit; update the branch'};
  }
  const commits = [];
  for (let page = 1; commits.length < window; page++) {
    const {data} = await github.rest.repos.listCommits({...repo, sha: pr.base.sha, per_page: PAGE, page});
    commits.push(...data);
    if (data.length < PAGE) break;
  }
  const links = chain(commits.slice(0, window), pr.base.sha);
  if (links.length === 0 || !links.every(commit => object(commit.commit.tree.sha))) return {matched: false, reason: 'the base history is unavailable'};
  const {trees, rolledBack, unjudged} = eligible(links);
  const tree = head.commit.tree.sha;
  if (tree === trees[0]) return {matched: false, reason: 'the pull request changes nothing'};
  const index = trees.indexOf(tree);
  if (index === -1) return {matched: false, reason: 'the resulting tree is not a tree of the base history within the window'};
  if (rolledBack.has(tree)) return {matched: false, reason: 'the resulting tree was rolled back by a later base commit'};
  if (unjudged.has(tree)) return {matched: false, reason: 'the base history within the window cannot show that the tree was never rolled back'};
  return {matched: true, tree, matched_commit: links[index].sha, distance: index, window,
    head_sha: pr.head.sha, base_sha: pr.base.sha};
}

const text = verdict => `Exact revert accepted without an AI review: the resulting tree ${verdict.tree.slice(0, 12)} is byte-identical to the tree of ` +
  `base commit ${verdict.matched_commit.slice(0, 12)}, ${verdict.distance} commit(s) back on the first-parent history. CI AI calls: 0.`;

// Hosted assessment. Returns a complete assessment and writes the record, or null so the ordinary review continues. A
// change to protected review controls is accepted only with the exact-head owner confirmation, as everywhere else.
async function assess({github, repo, pr, files, comments, technical, legacy, config, engine, identity, recordPath, report}) {
  const note = line => {if (report) report(line);};
  const managed = await legacy.managedExemptions(github, repo, pr, files);
  const controls = legacy.scopeReason(files, pr, managed.exempt);
  if (controls && controls !== legacy.REVIEW_CONTROL_REASON) {
    note(`Exact revert not applied: ${controls}.`);
    return null;
  }
  const authorization = controls ? await legacy.purposeConfirmation(github, repo, pr, comments) : null;
  if (controls && !authorization) {
    note('Exact revert not applied: protected review controls changed and the exact-head owner confirmation is missing.');
    return null;
  }
  const verdict = await verify({github, repo, pr, window: config.exact_revert.window});
  if (!verdict.matched) {
    note(`Exact revert not applied: ${verdict.reason}.`);
    return null;
  }
  const record = {version: 2, ...(engine ? {engine} : {}), exact_revert: verdict, snapshot: {repository: `${repo.owner}/${repo.repo}`},
    controls: Boolean(controls), technical, ...(authorization ? {local_authorization: authorization} : {})};
  require('node:fs').writeFileSync(recordPath, JSON.stringify(record, null, 2) + '\n');
  note(text(verdict));
  return {...identity, decision: authorization ? 'owner_decision' : 'auto_approve', record_digest: digest(record),
    review_source: 'exact_revert', provider_api_calls: 0,
    reason: `Exact revert: the tree is byte-identical to previously accepted base commit ${verdict.matched_commit}; no AI rerun.`};
}

// Everything the gate and the atomic write boundary re-derive from the trusted side, never from the stored verdict alone.
async function verifyRecord({github, repo, record, assessment, config, engine, numberFor, context, legacy}) {
  const expected = record.local_authorization ? 'owner_decision' : 'auto_approve';
  if (!config.exact_revert || assessment.version !== 2 || assessment.review_source !== 'exact_revert' ||
      digest(record) !== assessment.record_digest || assessment.record_reference_digest !== undefined ||
      assessment.decision !== expected || record.exact_revert.head_sha !== assessment.head_sha ||
      record.exact_revert.base_sha !== assessment.base_sha || record.exact_revert.window !== config.exact_revert.window ||
      record.snapshot.repository !== `${repo.owner}/${repo.repo}` ||
      (engine && (digest(record.engine) !== digest(engine) || digest(assessment.engine) !== digest(engine)))) {
    throw new Error('Stale or altered exact-revert record');
  }
  const {data: pr} = await require('./pull-read.cjs').readPull(github, repo, numberFor(context));
  const branchUpdate = require('./branch-update.cjs');
  if (branchUpdate.baseOnlyMoved(pr, assessment, config.base_branch)) {
    throw await branchUpdate.surface({github, repo, pr, assessment, baseBranch: config.base_branch});
  }
  if (pr.head.sha !== assessment.head_sha || pr.base.sha !== assessment.base_sha) throw new Error('PR changed after exact-revert investigation');
  const fresh = await verify({github, repo, pr, window: config.exact_revert.window});
  if (digest(fresh) !== digest(record.exact_revert)) throw new Error('Exact-revert evidence changed after investigation');
  const technical = await legacy.technicalRun(github, repo, pr, {receipt: true});
  if (digest(technical) !== digest(record.technical)) throw new Error('Verification changed after exact-revert investigation');
  const comments = await github.paginate(github.rest.issues.listComments, {...repo, issue_number: pr.number, per_page: 100});
  if (record.local_authorization && digest(record.local_authorization) !== digest(await legacy.purposeConfirmation(github, repo, pr, comments))) {
    throw new Error('Exact-revert owner authorization changed; confirm this exact revision again');
  }
  return {pr, comments, verdict: fresh};
}

async function gate({github, context, core, assessment, record, config, engine, legacy, numberFor, options}) {
  const repo = context.repo;
  const check = () => verifyRecord({github, repo, record, assessment, config, engine, numberFor, context, legacy});
  const {pr, comments, verdict} = await check();
  await require('./incomplete.cjs').resolvePending({github, context, number: assessment.number});
  const body = `${MARKER}\n## Clouseau exact revert\n\n${text(verdict)} The protected-control and verification rules were applied unchanged.`;
  const existing = comments.find(item => item.user?.login === 'github-actions[bot]' && item.body.startsWith(`${MARKER}\n`));
  if (existing) await github.rest.issues.updateComment({...repo, comment_id: existing.id, body});
  else await github.rest.issues.createComment({...repo, issue_number: pr.number, body});
  await core.summary.addRaw(body).write();
  return legacy.gate({github, context, core, ...options, verifyAcceptance: async () => {await check();},
    assessment: {...assessment, decision: assessment.decision === 'owner_decision' ? 'second_opinion' : 'auto_approve'}});
}

module.exports = {MAX_WINDOW, MARKER, validate, chain, eligible, verify, assess, verifyRecord, gate};

'use strict';

const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const exact = require('./exact-revert.cjs');
const {validateConfig} = require('./config.cjs');
const {digest} = require('./acceptance.cjs');

const id = (letter, length = 40) => letter.repeat(length);
const BASE = id('b');
const HEAD = id('e');
const repo = {owner: 'o', repo: 'r'};

// History is newest first: {sha, tree, parents}. `parents` defaults to the next commit.
function history(rows) {
  return rows.map((row, index) => ({sha: row.sha, parents: (row.parents ?? (rows[index + 1] ? [rows[index + 1].sha] : [])).map(sha => ({sha})),
    commit: {tree: {sha: row.tree}}}));
}

function world({rows, headTree = id('1'), status = 'ahead', mergeBase = BASE, headSha = HEAD}) {
  const commits = history(rows);
  return {github: {rest: {repos: {
    getCommit: async ({ref}) => ({data: {sha: headSha, commit: {tree: {sha: headTree}}, ref}}),
    compareCommitsWithBasehead: async ({basehead}) => ({data: {status, merge_base_commit: {sha: mergeBase}, basehead}}),
    listCommits: async ({page, per_page}) => ({data: commits.slice((page - 1) * per_page, page * per_page)}),
  }}}};
}

const pr = {number: 3, head: {sha: HEAD}, base: {sha: BASE, ref: 'main'}};
const run = (w, window = 10) => exact.verify({github: w.github, repo, pr, window});
const linear = (...trees) => trees.map((tree, index) => ({sha: index === 0 ? BASE : id('cdfghijk'[index]), tree: id(tree)}));

test('configuration is validated and only in protected configuration for protocol version two', () => {
  assert.deepEqual(exact.validate({window: 2}), {window: 2});
  for (const bad of [null, [], 'x', {}, {window: 1}, {window: 201}, {window: 2.5}, {window: '9'}, {window: 9, extra: 1}]) {
    assert.throws(() => exact.validate(bad), /Invalid exact_revert configuration/, JSON.stringify(bad));
  }
  const base = {...require('../test/fixtures/config.json'), version: 2, repository_policy: '.github/clouseau.md',
    acceptance: {examiner: 'deepseek-flash', challenger: 'deepseek-flash', grader: 'deepseek', grading_model: 'deepseek-flash', repair_attempts: 2}};
  assert.deepEqual(validateConfig({...base, exact_revert: {window: 50}}).exact_revert, {window: 50});
  assert.equal('exact_revert' in validateConfig(base), false);
  assert.throws(() => validateConfig({...base, exact_revert: {window: 1}}), /Invalid exact_revert/);
  assert.throws(() => validateConfig({...base, version: 1, acceptance: undefined, exact_revert: {window: 50}}), /requires acceptance protocol version two/);
});

test('an exact revert of the previous change matches the earlier accepted tree', async () => {
  // tip B (tree 2) changed A (tree 1); the PR restores tree 1.
  const verdict = await run(world({rows: linear('2', '1', '0', '9')}));
  assert.deepEqual(verdict, {matched: true, tree: id('1'), matched_commit: id('d'), distance: 1, window: 10, head_sha: HEAD, base_sha: BASE});
});

test('a root commit tree can be restored because nothing precedes it to be rolled back', async () => {
  assert.equal((await run(world({rows: linear('2', '1')}))).matched, true);
});

test('attacker: a tree that exists only on an unmerged branch or fork is not in the base history', async () => {
  const verdict = await run(world({rows: linear('2', '1', '0', '9'), headTree: id('7')}));
  assert.deepEqual(verdict, {matched: false, reason: 'the resulting tree is not a tree of the base history within the window'});
});

test('attacker: a side-branch commit merged by a merge commit is never an accepted state', async () => {
  const rows = [{sha: BASE, tree: id('4'), parents: [id('c'), id('d')]}, {sha: id('c'), tree: id('3'), parents: [id('f')]},
    {sha: id('d'), tree: id('5'), parents: [id('f')]}, {sha: id('f'), tree: id('1'), parents: [id('g')]}, {sha: id('g'), tree: id('0'), parents: []}];
  // Tree 5 only ever existed on the merged side branch: not on the first-parent chain.
  assert.equal((await run(world({rows, headTree: id('5')}))).matched, false);
  // The first-parent state before the merge is accepted (merge commit trees too).
  assert.equal((await run(world({rows, headTree: id('3')}))).matched, true);
  assert.equal((await run(world({rows, headTree: id('1')}))).matched, true);
});

test('attacker: a tree the history itself rolled back cannot be reinstated by reverting the revert', async () => {
  // 0 -> bad change (1) -> revert restores 0 (tip). Reverting the revert would reinstate 1.
  const rows = linear('0', '1', '0', '9');
  const verdict = await run(world({rows, headTree: id('1')}));
  assert.deepEqual(verdict, {matched: false, reason: 'the resulting tree was rolled back by a later base commit'});
  // The oldest tree (a root commit) was never rolled back and is still restorable.
  assert.equal((await run(world({rows, headTree: id('9')}))).matched, true);
});

test('attacker: a tree outside the history window, or whose predecessor lies outside it, is not accepted', async () => {
  const rows = linear('5', '4', '3', '2', '1');
  assert.equal((await run(world({rows, headTree: id('2')}), 3)).reason, 'the resulting tree is not a tree of the base history within the window');
  const unjudged = await run(world({rows, headTree: id('3')}), 3);
  assert.equal(unjudged.reason, 'the base history within the window cannot show that the tree was never rolled back');
  assert.equal((await run(world({rows, headTree: id('4')}), 3)).matched, true);
});

test('attacker: force-pushed history is judged only from the immutable base commit that the PR names', async () => {
  // The rewritten history does not list the old commit, so its tree is absent and nothing matches.
  const rewritten = world({rows: linear('2', '8', '0', '9'), headTree: id('1')});
  assert.equal((await run(rewritten)).matched, false);
  // A base commit that the listing does not return first yields no chain at all.
  const unrelated = world({rows: linear('2', '1').map(row => ({...row, sha: id('c') + row.sha.slice(1)}))});
  assert.deepEqual(await run(unrelated), {matched: false, reason: 'the base history is unavailable'});
  const malformed = world({rows: [{sha: BASE, tree: 'nothex'}, {sha: id('a'), tree: id('1')}]});
  assert.equal((await run(malformed)).reason, 'the base history is unavailable');
});

test('attacker: the head must be the PR head, the PR must sit on the current base, and an empty change is no revert', async () => {
  assert.equal((await run(world({rows: linear('2', '1'), headSha: id('f')}))).reason, 'the head commit tree is unavailable');
  assert.equal((await run(world({rows: linear('2', '1'), headTree: 'short'}))).reason, 'the head commit tree is unavailable');
  for (const status of ['diverged', 'behind', 'identical']) {
    assert.match((await run(world({rows: linear('2', '1'), status}))).reason, /not based on the current base commit/, status);
  }
  assert.match((await run(world({rows: linear('2', '1'), mergeBase: id('c')}))).reason, /not based on the current base commit/);
  assert.equal((await run(world({rows: linear('2', '1'), headTree: id('2')}))).reason, 'the pull request changes nothing');
});

test('history is read in bounded pages and a window larger than the history stops at its end', async () => {
  const rows = Array.from({length: 150}, (_, index) => ({sha: index === 0 ? BASE : index.toString(16).padStart(40, 'a'), tree: index.toString(16).padStart(40, '0')}));
  const pages = [];
  const w = world({rows, headTree: rows[110].tree});
  const list = w.github.rest.repos.listCommits;
  w.github.rest.repos.listCommits = async args => {pages.push(args.page); return list(args);};
  assert.equal((await run(w, 120)).matched, true);
  assert.deepEqual(pages, [1, 2]);
  pages.length = 0;
  assert.equal((await run(w, 100)).matched, false);
  assert.deepEqual(pages, [1]);
  pages.length = 0;
  assert.equal((await run(w, 200)).matched, true);
  assert.deepEqual(pages, [1, 2]);
});

function stub({controls = null, authorization = null, exempt = new Set()} = {}) {
  const calls = [];
  return {calls, REVIEW_CONTROL_REASON: 'controls', managedExemptions: async () => ({exempt, notices: []}),
    scopeReason: (_files, _pr, got) => {calls.push(got); return controls;}, purposeConfirmation: async () => authorization};
}

test('assessment writes a zero-AI record, requires owner confirmation for protected controls and otherwise continues the review', async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'exact-revert-'));
  try {
    const recordPath = path.join(dir, 'record.json');
    const w = world({rows: linear('2', '1', '0', '9')});
    const reports = [];
    const common = {github: w.github, repo, pr, files: [], comments: [], technical: {state: 'ok'}, config: {exact_revert: {window: 10}},
      identity: {version: 2, number: 3, head_sha: HEAD, base_sha: BASE}, recordPath, report: line => reports.push(line)};
    const accepted = await exact.assess({...common, legacy: stub(), engine: {sha: 'x'}});
    assert.equal(accepted.decision, 'auto_approve');
    assert.equal(accepted.review_source, 'exact_revert');
    assert.equal(accepted.provider_api_calls, 0);
    const record = JSON.parse(fs.readFileSync(recordPath));
    assert.equal(accepted.record_digest, digest(record));
    assert.deepEqual([record.controls, record.engine, record.snapshot], [false, {sha: 'x'}, {repository: 'o/r'}]);
    assert.ok('local_authorization' in record === false);
    assert.match(reports.at(-1), /^Exact revert accepted without an AI review: the resulting tree 111111111111 is byte-identical .* CI AI calls: 0\.$/);
    // No report sink and no engine are fine.
    assert.equal((await exact.assess({...common, report: undefined, legacy: stub()})).decision, 'auto_approve');

    const authorization = {comment_id: 4};
    const owner = await exact.assess({...common, legacy: stub({controls: 'controls', authorization})});
    assert.equal(owner.decision, 'owner_decision');
    assert.deepEqual(JSON.parse(fs.readFileSync(recordPath)).local_authorization, authorization);

    fs.rmSync(recordPath);
    reports.length = 0;
    assert.equal(await exact.assess({...common, legacy: stub({controls: 'controls'})}), null);
    assert.match(reports[0], /^Exact revert not applied: protected review controls changed and the exact-head owner confirmation is missing\.$/);
    assert.equal(await exact.assess({...common, legacy: stub({controls: 'Incomplete changed-file list'})}), null);
    assert.equal(reports[1], 'Exact revert not applied: Incomplete changed-file list.');
    assert.equal(await exact.assess({...common, report: undefined, legacy: stub({controls: 'Incomplete changed-file list'})}), null);
    const miss = world({rows: linear('2', '1'), headTree: id('7')});
    assert.equal(await exact.assess({...common, github: miss.github, legacy: stub()}), null);
